update public.horses h set visual_phenotype=jsonb_set(jsonb_set(h.visual_phenotype,'{background}','"pure neutral white RGB 255 255 255 seamless background, edge-to-edge and shadow-free except for a faint natural hoof contact shadow"'::jsonb,true),'{lighting}','"bright neutral daylight, crisp coat detail, clean highlights, accurate coat color, strong natural contrast and no color cast"'::jsonb,true),image_generation_status='pending',image_prompt_version='store-horse-v4' from public.store_inventory si where si.horse_id=h.id and si.status='active';
insert into public.store_horse_image_jobs(horse_id,status,attempts,next_attempt_at,last_error,completed_at) select h.id,'pending',0,now(),null,null from public.horses h join public.store_inventory si on si.horse_id=h.id where si.status='active' on conflict(horse_id) do update set status='pending',attempts=0,next_attempt_at=now(),last_error=null,completed_at=null;
